package pl.srgmobile.classic;

import android.app.Activity;
import android.content.Intent;
import android.content.pm.PackageInfo;
import android.content.pm.PackageManager;
import android.os.Build;
import android.provider.Settings;
import android.net.Uri;
import android.webkit.JavascriptInterface;
import androidx.core.content.FileProvider;
import org.json.*;
import java.io.*;
import java.net.*;
import java.security.MessageDigest;
import java.util.*;
import java.util.concurrent.*;
import java.util.regex.*;

/** GitHub release APKs only, matching this installed edition and signing certificate. */
final class ApkUpdates implements AutoCloseable {
    private static final String API="https://api.github.com/repos/projekt-debica-omsi2/srg/releases?per_page=15";
    private static final String DOWNLOAD="https://github.com/projekt-debica-omsi2/srg/releases/download/";
    private final Activity activity;private final ExecutorService worker=Executors.newSingleThreadExecutor();
    private volatile String status="Sprawdzanie aktualizacji jest opcjonalne",version="";private volatile JSONObject asset;private volatile boolean busy=false;private File ready;
    ApkUpdates(Activity a){activity=a;if(a.getSharedPreferences("updates",0).getBoolean("automatic",false))check();}
    static boolean matchesEdition(String name,String pkg){String n=name.toLowerCase(Locale.ROOT);if(!n.startsWith("srgmobile")||!n.endsWith(".apk"))return false;boolean gps=n.contains("testgps"),pub=n.contains("public"),test=n.contains("test");if(pkg.endsWith(".testgps"))return gps&&!pub;if(pkg.endsWith(".publicapp"))return pub&&!gps;if(pkg.endsWith(".test"))return test&&!gps&&!pub;return !gps&&!pub&&!test;}
    static int[] semver(String text){Matcher m=Pattern.compile("(\\d+)\\.(\\d+)\\.(\\d+)").matcher(text);if(!m.find())return new int[]{0,0,0};try{return new int[]{Integer.parseInt(m.group(1)),Integer.parseInt(m.group(2)),Integer.parseInt(m.group(3))};}catch(Exception e){return new int[]{0,0,0};}}
    static boolean newer(String candidate,String installed){int[] a=semver(candidate),b=semver(installed);for(int i=0;i<3;i++)if(a[i]!=b[i])return a[i]>b[i];return false;}
    private PackageInfo installed() throws Exception{return activity.getPackageManager().getPackageInfo(activity.getPackageName(),(Build.VERSION.SDK_INT>=28?PackageManager.GET_SIGNING_CERTIFICATES:PackageManager.GET_SIGNATURES));}
    private HttpURLConnection open(String url) throws Exception{HttpURLConnection c=(HttpURLConnection)new URL(url).openConnection();c.setConnectTimeout(15000);c.setReadTimeout(30000);c.setRequestProperty("User-Agent","SRGMobile-Update");c.setRequestProperty("Accept","application/vnd.github+json");return c;}
    @JavascriptInterface public String state(){try{return new JSONObject().put("status",status).put("version",version).put("available",asset!=null).put("ready",ready!=null).put("busy",busy).put("automatic",activity.getSharedPreferences("updates",0).getBoolean("automatic",false)).toString();}catch(Exception e){return "{}";}}
    @JavascriptInterface public void automatic(boolean value){activity.getSharedPreferences("updates",0).edit().putBoolean("automatic",value).apply();}
    @JavascriptInterface public synchronized void check(){if(busy)return;busy=true;status="Sprawdzam wydania GitHub…";worker.execute(()->{HttpURLConnection c=null;try{c=open(API);if(c.getResponseCode()!=200)throw new IOException("GitHub HTTP "+c.getResponseCode());String body;try(InputStream in=c.getInputStream()){ByteArrayOutputStream out=new ByteArrayOutputStream();byte[] buf=new byte[16384];int n;while((n=in.read(buf))!=-1){out.write(buf,0,n);if(out.size()>4*1024*1024)throw new IOException("Za duża lista wydań");}body=new String(out.toByteArray(),java.nio.charset.StandardCharsets.UTF_8);}JSONArray releases=new JSONArray(body);String current=installed().versionName,best=current;JSONObject found=null;for(int i=0;i<releases.length();i++){JSONObject r=releases.getJSONObject(i);if(r.optBoolean("draft")||r.optBoolean("prerelease"))continue;JSONArray assets=r.optJSONArray("assets");if(assets==null)continue;for(int k=0;k<assets.length();k++){JSONObject a=assets.getJSONObject(k);String name=a.optString("name"),url=a.optString("browser_download_url"),tag=r.optString("tag_name");String label=semver(name)[0]>0?name:tag;if(matchesEdition(name,activity.getPackageName())&&url.startsWith(DOWNLOAD)&&newer(label,best)){best=label;found=a;}}}asset=found;version=found==null?"":best;ready=null;status=found==null?"Brak nowszego APK dla tej wersji aplikacji":"Dostępna aktualizacja: "+best;}catch(Exception e){status="Nie sprawdzono aktualizacji: "+e.getMessage();}finally{if(c!=null)c.disconnect();busy=false;}});}
    @JavascriptInterface public synchronized void download(){if(busy||asset==null)return;JSONObject selected=asset;busy=true;status="Pobieram APK…";worker.execute(()->{HttpURLConnection c=null;try{String url=selected.getString("browser_download_url");if(!url.startsWith(DOWNLOAD))throw new IOException("Nieprawidłowe źródło APK");c=open(url);if(c.getResponseCode()!=200)throw new IOException("Pobieranie HTTP "+c.getResponseCode());File dir=new File(activity.getCacheDir(),"updates");dir.mkdirs();File file=new File(dir,"SRGMobile-update.apk");MessageDigest digest=MessageDigest.getInstance("SHA-256");long count=0;try(InputStream in=c.getInputStream();OutputStream out=new FileOutputStream(file)){byte[] buffer=new byte[32768];int n;while((n=in.read(buffer))!=-1){count+=n;if(count>150L*1024*1024)throw new IOException("APK przekracza150MB");out.write(buffer,0,n);digest.update(buffer,0,n);}}String expected=selected.optString("digest");StringBuilder hash=new StringBuilder();for(byte b:digest.digest())hash.append(String.format(Locale.ROOT,"%02x",b));if(expected.startsWith("sha256:")&&!expected.equals("sha256:"+hash))throw new IOException("Suma SHA256 nie pasuje");PackageInfo archive=activity.getPackageManager().getPackageArchiveInfo(file.getAbsolutePath(),(Build.VERSION.SDK_INT>=28?PackageManager.GET_SIGNING_CERTIFICATES:PackageManager.GET_SIGNATURES));PackageInfo current=installed();if(archive==null||!activity.getPackageName().equals(archive.packageName))throw new IOException("APK należy do innej wersji aplikacji");long next=Build.VERSION.SDK_INT>=28?archive.getLongVersionCode():archive.versionCode,old=Build.VERSION.SDK_INT>=28?current.getLongVersionCode():current.versionCode;if(next<=old)throw new IOException("APK nie jest nowszy od zainstalowanego");if(!sameSigners(archive,current))throw new IOException("Podpis APK różni się od zainstalowanej aplikacji");ready=file;status="APK sprawdzony. Naciśnij Zainstaluj aktualizację.";}catch(Exception e){ready=null;status="Nie przygotowano instalacji: "+e.getMessage();}finally{if(c!=null)c.disconnect();busy=false;}});}
    private boolean sameSigners(PackageInfo a,PackageInfo b){android.content.pm.Signature[] first,second;if(Build.VERSION.SDK_INT>=28){if(a.signingInfo==null||b.signingInfo==null)return false;first=a.signingInfo.hasMultipleSigners()?a.signingInfo.getApkContentsSigners():a.signingInfo.getSigningCertificateHistory();second=b.signingInfo.hasMultipleSigners()?b.signingInfo.getApkContentsSigners():b.signingInfo.getSigningCertificateHistory();}else{first=a.signatures;second=b.signatures;}if(first==null||second==null)return false;Set<String> x=new HashSet<>(),y=new HashSet<>();for(android.content.pm.Signature s:first)x.add(s.toCharsString());for(android.content.pm.Signature s:second)y.add(s.toCharsString());if(first.length>1||second.length>1)return x.equals(y);x.retainAll(y);return !x.isEmpty();}
    @JavascriptInterface public void install(){File file=ready;if(file==null)return;activity.runOnUiThread(()->{try{if(Build.VERSION.SDK_INT>=26&&!activity.getPackageManager().canRequestPackageInstalls()){status="Zezwól Androidowi na instalację z SRGMobile, wróć i naciśnij Zainstaluj ponownie.";activity.startActivity(new Intent(Settings.ACTION_MANAGE_UNKNOWN_APP_SOURCES,Uri.parse("package:"+activity.getPackageName())));return;}Uri uri=FileProvider.getUriForFile(activity,activity.getPackageName()+".updates",file);activity.startActivity(new Intent(Intent.ACTION_VIEW).setDataAndType(uri,"application/vnd.android.package-archive").addFlags(Intent.FLAG_GRANT_READ_URI_PERMISSION));}catch(Exception e){status="Nie otwarto instalatora: "+e.getMessage();}});}
    public void close(){worker.shutdownNow();}
}
